function onRequest(request, response) {
    var frontUrl = '';
    if(request.url === '/favicon.ico') return;
    for(var key in conf.serv) {
      if(request.headers.host.indexOf(key) !== -1) {
        host = conf.serv[key];
      }
    }

    var nowTemp = host.frondend + (request.url.replace('/', '') || host.baseTemp);
    var httpHead = header(nowTemp);
    conf.app = conf.getApp(host.backend);
    if(!host) {
      error(response);
      return;
    }

    var defaultTemp = function() {
      fs.readFile(host.frondend + host.baseTemp, function(err, file) {
        if(err) {
          error(response, err);
          return;
        }
        responseTemp(response, httpHead, file);
      });
    };

    var send = function(res) {
      if(res) {
        if(res === 'error') {
          error(response, 'Route config error!');
          return;
        }

        if(res.html) {
          response.writeHead(res.status, {'Content-Type': 'text/html;charset:utf-8'});
          response.write(res.html);
          response.end();
          return;
        } else if(res.status === 302) {
          response.writeHead(res.status, {
            'Content-Type': 'text/html;charset:utf-8',
            'Location': res.url
          });
          response.end();
          return;
        } else if(res.data) {
          response.writeHead(res.status, {'Content-Type': 'application/json'});
          response.write(JSON.stringify(res));
          response.end();
          return;
        } else {
          error(response, 'Data type error!');
        }
      } else {
        fs.exists(nowTemp, function(exists) {
          if(!exists) {
            defaultTemp();
          } else {
            fs.readFile(nowTemp, function(err, file) {
              if (err) {
                defaultTemp();
              } else {
                responseTemp(response, httpHead, file);
              }
            });
          }
        });
      }
    };

    route(conf.app.url, request, send);
  }

async createHandler(req, res, next) {
    const config = req.config;
    const user = req.auth.user;
    const isMaster = req.auth.isMaster;
    const isLinked = user && Parse.AnonymousUtils.isLinked(user);
    if (!isMaster && !config.fileUpload.enableForAnonymousUser && isLinked) {
      next(
        new Parse.Error(Parse.Error.FILE_SAVE_ERROR, 'File upload by anonymous user is disabled.')
      );
      return;
    }
    if (!isMaster && !config.fileUpload.enableForAuthenticatedUser && !isLinked && user) {
      next(
        new Parse.Error(
          Parse.Error.FILE_SAVE_ERROR,
          'File upload by authenticated user is disabled.'
        )
      );
      return;
    }
    if (!isMaster && !config.fileUpload.enableForPublic && !user) {
      next(new Parse.Error(Parse.Error.FILE_SAVE_ERROR, 'File upload by public is disabled.'));
      return;
    }
    const filesController = config.filesController;
    const { filename } = req.params;
    const contentType = req.get('Content-type');

    if (!req.body || !req.body.length) {
      next(new Parse.Error(Parse.Error.FILE_SAVE_ERROR, 'Invalid file upload.'));
      return;
    }

    const error = filesController.validateFilename(filename);
    if (error) {
      next(error);
      return;
    }

    const fileExtensions = config.fileUpload?.fileExtensions;
    if (!isMaster && fileExtensions) {
      const isValidExtension = extension => {
        return fileExtensions.some(ext => {
          if (ext === '*') {
            return true;
          }
          const regex = new RegExp(fileExtensions);
          if (regex.test(extension)) {
            return true;
          }
        });
      };
      let extension = contentType;
      if (filename && filename.includes('.')) {
        extension = filename.split('.')[1];
      } else if (contentType && contentType.includes('/')) {
        extension = contentType.split('/')[1];
      }
      extension = extension.split(' ').join('');

      if (!isValidExtension(extension)) {
        next(
          new Parse.Error(
            Parse.Error.FILE_SAVE_ERROR,
            `File upload of extension ${extension} is disabled.`
          )
        );
        return;
      }
    }

    const base64 = req.body.toString('base64');
    const file = new Parse.File(filename, { base64 }, contentType);
    const { metadata = {}, tags = {} } = req.fileData || {};
    if (req.config && req.config.requestKeywordDenylist) {
      for (const keyword of req.config.requestKeywordDenylist) {
        const match =
          Utils.objectContainsKeyValue(metadata, keyword.key, keyword.value) ||
          Utils.objectContainsKeyValue(tags, keyword.key, keyword.value);
        if (match) {
          next(
            new Parse.Error(
              Parse.Error.INVALID_KEY_NAME,
              `Prohibited keyword in request data: ${JSON.stringify(keyword)}.`
            )
          );
          return;
        }
      }
    }
    file.setTags(tags);
    file.setMetadata(metadata);
    const fileSize = Buffer.byteLength(req.body);
    const fileObject = { file, fileSize };
    try {
      const triggerResult = await triggers.maybeRunFileTrigger(
        triggers.Types.beforeSave,
        fileObject,
        config,
        req.auth
      );
      let saveResult;
      if (triggerResult instanceof Parse.File) {
        fileObject.file = triggerResult;
        if (triggerResult.url()) {
          fileObject.fileSize = null;
          saveResult = {
            url: triggerResult.url(),
            name: triggerResult._name,
          };
        }
      }
      if (!saveResult) {
        await addFileDataIfNeeded(fileObject.file);
        const bufferData = Buffer.from(fileObject.file._data, 'base64');
        fileObject.fileSize = Buffer.byteLength(bufferData);
        const fileOptions = {
          metadata: fileObject.file._metadata,
        };
        const fileTags =
          Object.keys(fileObject.file._tags).length > 0 ? { tags: fileObject.file._tags } : {};
        Object.assign(fileOptions, fileTags);
        const createFileResult = await filesController.createFile(
          config,
          fileObject.file._name,
          bufferData,
          fileObject.file._source.type,
          fileOptions
        );
        fileObject.file._name = createFileResult.name;
        fileObject.file._url = createFileResult.url;
        fileObject.file._requestTask = null;
        fileObject.file._previousSave = Promise.resolve(fileObject.file);
        saveResult = {
          url: createFileResult.url,
          name: createFileResult.name,
        };
      }
      await triggers.maybeRunFileTrigger(triggers.Types.afterSave, fileObject, config, req.auth);
      res.status(201);
      res.set('Location', saveResult.url);
      res.json(saveResult);
    } catch (e) {
      logger.error('Error creating a file: ', e);
      const error = triggers.resolveError(e, {
        code: Parse.Error.FILE_SAVE_ERROR,
        message: `Could not store file: ${fileObject.file._name}.`,
      });
      next(error);
    }
  }

function dnsLookup (hostname, options, callback) {
  dns.lookup(hostname, options, (err, addresses, maybeFamily) => {
    if (err) {
      callback(err, addresses, maybeFamily)
      return
    }

    const toValidate = Array.isArray(addresses) ? addresses : [{ address: addresses }]
    for (const record of toValidate) {
      if (isDisallowedIP(record.address)) {
        callback(new Error(FORBIDDEN_IP_ADDRESS), addresses, maybeFamily)
        return
      }
    }

    callback(err, addresses, maybeFamily)
  })
}

static isPayloadValid(type, payload) {
        switch (type) {
            case PacketType.CONNECT:
                return isObject(payload);
            case PacketType.DISCONNECT:
                return payload === undefined;
            case PacketType.CONNECT_ERROR:
                return typeof payload === "string" || isObject(payload);
            case PacketType.EVENT:
            case PacketType.BINARY_EVENT:
                return (Array.isArray(payload) &&
                    (typeof payload[0] === "number" ||
                        (typeof payload[0] === "string" &&
                            RESERVED_EVENTS.indexOf(payload[0]) === -1)));
            case PacketType.ACK:
            case PacketType.BINARY_ACK:
                return Array.isArray(payload);
        }
    }

doDownloadTo(out) {
    const url = Url.parse(this.url);
    const options = {
      hostname: url.hostname,
      port: url.port,
      path: url.path,
    };

    let protocol;
    if (url.protocol === "http:" || url.protocol === "https:") {
      protocol = Request.defaults({
        maxRedirects: 20,
        strictSSL: false,
      });
    } else {
      throw new Error("Protocol not supported: " + url.protocol);
    }

    let bytesExpected = undefined;
    let bytesReceived = 0;
    const hasher = Crypto.createHash("sha256");
    let done = false;
    const updateDownloadProgress = _.throttle(this.wrapCallback(() => {
      if (!done) {
        if (bytesExpected) {
          this.updateProgress("download", bytesReceived / bytesExpected);
        } else {
          this.updateProgress("download", bytesReceived);
        }
      }
    }), 500);

    const request = protocol.get(this.url);

    request.on("response", this.wrapCallback((response) => {
      if ("content-length" in response.headers) {
        bytesExpected = parseInt(response.headers["content-length"]);
      }
    }));

    request.on("data", this.wrapCallback((chunk) => {
      hasher.update(chunk);
      out.write(chunk);
      bytesReceived += chunk.length;
      updateDownloadProgress();
    }));

    request.on("end", this.wrapCallback(() => {
      out.done();

      if (hasher.digest("hex").slice(0, 32) !== this.packageId) {
        throw new Error("Package hash did not match.");
      }

      done = true;
      delete this.downloadRequest;

      this.updateProgress("unpack");
      out.saveAs(this.packageId).then(this.wrapCallback((info) => {
        this.appId = info.appId;
        this.authorPgpKeyFingerprint = info.authorPgpKeyFingerprint;
        this.done(info.manifest);
      }), this.wrapCallback((err) => {
        throw err;
      }));
    }));

    request.on("error", this.wrapCallback((err) => { throw err; }));

    this.downloadRequest = request;
  }

httpGet(url) {
    const _this = this;
    const session = _this;

    return inMeteor(() => {
      return ssrfSafeLookup(globalDb, url);
    }).then(safe => {
      return new Promise((resolve, reject) => {
        let requestMethod = Http.request;
        if (safe.url.indexOf("https://") === 0) {
          requestMethod = Https.request;
        } else if (safe.url.indexOf("http://") !== 0) {
          err = new Error("Protocol not recognized.");
          err.nature = "precondition";
          reject(err);
        }

        const options = Url.parse(safe.url);
        options.headers = { host: safe.host };
        options.servername = safe.host.split(":")[0];

        req = requestMethod(options, (resp) => {
          const buffers = [];
          let err;

          switch (Math.floor(resp.statusCode / 100)) {
            case 2:
              resp.on("data", (buf) => {
                buffers.push(buf);
              });

              resp.on("end", () => {
                resolve({
                  content: Buffer.concat(buffers),
                  mimeType: resp.headers["content-type"] || null,
                });
              });
              break;
            case 3:
              resolve(session.httpGet(resp.headers.location));
              break;
            case 4:
              err = new Error("Status code " + resp.statusCode + " received in response.");
              err.nature = "precondition";
              reject(err);
              break;
            case 5:
              err = new Error("Status code " + resp.statusCode + " received in response.");
              err.nature = "localBug";
              reject(err);
              break;
            default:
              err = new Error("Invalid status code " + resp.statusCode + " received in response.");
              err.nature = "localBug";
              reject(err);
              break;
          }
        });

        req.on("error", (e) => {
          e.nature = "networkFailure";
          reject(e);
        });

        req.setTimeout(15000, () => {
          req.abort();
          err = new Error("Request timed out.");
          err.nature = "localBug";
          err.durability = "overloaded";
          reject(err);
        });

        req.end();
      });
    });
  }

