async function findImports({
  node,
  options,
  getNode,
  getNodes,
  getNodesByType,
  reporter,
  cache,
  pathPrefix,
  ...helpers
}) {
  const { content } = grayMatter(node.rawBody)

  const gatsbyRemarkPluginsAsremarkPlugins =
    await getSourcePluginsAsRemarkPlugins({
      gatsbyRemarkPlugins: options.gatsbyRemarkPlugins,
      mdxNode: node,
      getNode,
      getNodes,
      getNodesByType,
      reporter,
      cache,
      pathPrefix,
      compiler: {
        parseString: () => compiler.parse.bind(compiler),
        generateHTML: ast => mdx(ast, options),
      },
      ...helpers,
    })

  const compilerOptions = {
    filepath: node.fileAbsolutePath,
    ...options,
    remarkPlugins: [
      ...options.remarkPlugins,
      ...gatsbyRemarkPluginsAsremarkPlugins,
    ],
  }
  const compiler = mdx.createCompiler(compilerOptions)

  const fileOpts = { contents: content }
  if (node.fileAbsolutePath) {
    fileOpts.path = node.fileAbsolutePath
  }

  let mdast = await compiler.parse(fileOpts)
  mdast = await compiler.run(mdast, fileOpts)

  const identifiers = []
  const imports = []

  mdast.children.forEach(node => {
    if (node.type !== `import`) return

    const importCode = node.value

    imports.push(importCode)

    const bindings = parseImportBindings(importCode)
    identifiers.push(...bindings)
  })

  if (!identifiers.includes(`React`)) {
    identifiers.push(`React`)
    imports.push(`import * as React from 'react'`)
  }

  return {
    scopeImports: imports,
    scopeIdentifiers: identifiers,
  }
}

function $ParseProvider() {
	var cache = createMap();
	var literals = {
		true: true,
		false: false,
		null: null,
		undefined: undefined
	};
	var identStart, identContinue;

	this.addLiteral = function(literalName, literalValue) {
		literals[literalName] = literalValue;
	};

	this.setIdentifierFns = function(identifierStart, identifierContinue) {
		identStart = identifierStart;
		identContinue = identifierContinue;
		return this;
	};

	this.$get = [
		"$filter",
		function($filter) {
			var noUnsafeEval = csp().noUnsafeEval;
			var $parseOptions = {
				csp: noUnsafeEval,
				literals: copy(literals),
				isIdentifierStart: isFunction(identStart) && identStart,
				isIdentifierContinue: isFunction(identContinue) && identContinue
			};
			return $parse;

			function $parse(exp, interceptorFn) {
				var parsedExpression, oneTime, cacheKey;

				switch (typeof exp) {
					case "string":
						exp = exp.trim();
						cacheKey = exp;

						parsedExpression = cache[cacheKey];

						if (!parsedExpression) {
							if (exp.charAt(0) === ":" && exp.charAt(1) === ":") {
								oneTime = true;
								exp = exp.substring(2);
							}
							var lexer = new Lexer($parseOptions);
							var parser = new Parser(lexer, $filter, $parseOptions);
							parsedExpression = parser.parse(exp);
							if (parsedExpression.constant) {
								parsedExpression.$$watchDelegate = constantWatchDelegate;
							} else if (oneTime) {
								parsedExpression.$$watchDelegate = parsedExpression.literal
									? oneTimeLiteralWatchDelegate
									: oneTimeWatchDelegate;
							} else if (parsedExpression.inputs) {
								parsedExpression.$$watchDelegate = inputsWatchDelegate;
							}
							cache[cacheKey] = parsedExpression;
						}
						return addInterceptor(parsedExpression, interceptorFn);

					case "function":
						return addInterceptor(exp, interceptorFn);

					default:
						return addInterceptor(noop, interceptorFn);
				}
			}

			function expressionInputDirtyCheck(newValue, oldValueOfValue) {
				if (newValue == null || oldValueOfValue == null) {
					return newValue === oldValueOfValue;
				}

				if (typeof newValue === "object") {
					newValue = getValueOf(newValue);

					if (typeof newValue === "object") {
						return false;
					}

				}

				return (
					newValue === oldValueOfValue ||
					(newValue !== newValue && oldValueOfValue !== oldValueOfValue)
				);
			}

			function inputsWatchDelegate(
				scope,
				listener,
				objectEquality,
				parsedExpression,
				prettyPrintExpression
			) {
				var inputExpressions = parsedExpression.inputs;
				var lastResult;

				if (inputExpressions.length === 1) {
					var oldInputValueOf = expressionInputDirtyCheck;
					inputExpressions = inputExpressions[0];
					return scope.$watch(
						function expressionInputWatch(scope) {
							var newInputValue = inputExpressions(scope);
							if (!expressionInputDirtyCheck(newInputValue, oldInputValueOf)) {
								lastResult = parsedExpression(scope, undefined, undefined, [
									newInputValue
								]);
								oldInputValueOf = newInputValue && getValueOf(newInputValue);
							}
							return lastResult;
						},
						listener,
						objectEquality,
						prettyPrintExpression
					);
				}

				var oldInputValueOfValues = [];
				var oldInputValues = [];
				for (var i = 0, ii = inputExpressions.length; i < ii; i++) {
					oldInputValueOfValues[i] = expressionInputDirtyCheck;
					oldInputValues[i] = null;
				}

				return scope.$watch(
					function expressionInputsWatch(scope) {
						var changed = false;

						for (var i = 0, ii = inputExpressions.length; i < ii; i++) {
							var newInputValue = inputExpressions[i](scope);
							if (
								changed ||
								(changed = !expressionInputDirtyCheck(
									newInputValue,
									oldInputValueOfValues[i]
								))
							) {
								oldInputValues[i] = newInputValue;
								oldInputValueOfValues[i] =
									newInputValue && getValueOf(newInputValue);
							}
						}

						if (changed) {
							lastResult = parsedExpression(
								scope,
								undefined,
								undefined,
								oldInputValues
							);
						}

						return lastResult;
					},
					listener,
					objectEquality,
					prettyPrintExpression
				);
			}

			function oneTimeWatchDelegate(
				scope,
				listener,
				objectEquality,
				parsedExpression,
				prettyPrintExpression
			) {
				var unwatch, lastValue;
				if (parsedExpression.inputs) {
					unwatch = inputsWatchDelegate(
						scope,
						oneTimeListener,
						objectEquality,
						parsedExpression,
						prettyPrintExpression
					);
				} else {
					unwatch = scope.$watch(oneTimeWatch, oneTimeListener, objectEquality);
				}
				return unwatch;

				function oneTimeWatch(scope) {
					return parsedExpression(scope);
				}
				function oneTimeListener(value, old, scope) {
					lastValue = value;
					if (isFunction(listener)) {
						listener(value, old, scope);
					}
					if (isDefined(value)) {
						scope.$$postDigest(function() {
							if (isDefined(lastValue)) {
								unwatch();
							}
						});
					}
				}
			}

			function oneTimeLiteralWatchDelegate(
				scope,
				listener,
				objectEquality,
				parsedExpression
			) {
				var unwatch, lastValue;
				unwatch = scope.$watch(
					function oneTimeWatch(scope) {
						return parsedExpression(scope);
					},
					function oneTimeListener(value, old, scope) {
						lastValue = value;
						if (isFunction(listener)) {
							listener(value, old, scope);
						}
						if (isAllDefined(value)) {
							scope.$$postDigest(function() {
								if (isAllDefined(lastValue)) unwatch();
							});
						}
					},
					objectEquality
				);

				return unwatch;

				function isAllDefined(value) {
					var allDefined = true;
					forEach(value, function(val) {
						if (!isDefined(val)) allDefined = false;
					});
					return allDefined;
				}
			}

			function constantWatchDelegate(
				scope,
				listener,
				objectEquality,
				parsedExpression
			) {
				var unwatch = scope.$watch(
					function constantWatch(scope) {
						unwatch();
						return parsedExpression(scope);
					},
					listener,
					objectEquality
				);
				return unwatch;
			}

			function addInterceptor(parsedExpression, interceptorFn) {
				if (!interceptorFn) return parsedExpression;
				var watchDelegate = parsedExpression.$$watchDelegate;
				var useInputs = false;

				var regularWatch =
					watchDelegate !== oneTimeLiteralWatchDelegate &&
					watchDelegate !== oneTimeWatchDelegate;

				var fn = regularWatch
					? function regularInterceptedExpression(
							scope,
							locals,
							assign,
							inputs
					  ) {
							var value =
								useInputs && inputs
									? inputs[0]
									: parsedExpression(scope, locals, assign, inputs);
							return interceptorFn(value, scope, locals);
					  }
					: function oneTimeInterceptedExpression(
							scope,
							locals,
							assign,
							inputs
					  ) {
							var value = parsedExpression(scope, locals, assign, inputs);
							var result = interceptorFn(value, scope, locals);
							return isDefined(value) ? result : value;
					  };

				useInputs = !parsedExpression.inputs;
				if (
					parsedExpression.$$watchDelegate &&
					parsedExpression.$$watchDelegate !== inputsWatchDelegate
				) {
					fn.$$watchDelegate = parsedExpression.$$watchDelegate;
					fn.inputs = parsedExpression.inputs;
				} else if (!interceptorFn.$stateful) {
					fn.$$watchDelegate = inputsWatchDelegate;
					fn.inputs = parsedExpression.inputs
						? parsedExpression.inputs
						: [parsedExpression];
				}

				return fn;
			}
		}
	];
}

constructor(container, items, groups, options) {
    super()
    this.initTime = new Date();
    this.itemsDone = false;

    if (!(this instanceof Timeline)) {
      throw new SyntaxError('Constructor must be called with the new operator');
    }

    if (!(Array.isArray(groups) || isDataViewLike("id", groups)) && groups instanceof Object) {
      const forthArgument = options;
      options = groups;
      groups = forthArgument;
    }

    if (options && options.throttleRedraw) {
      console.warn("Timeline option \"throttleRedraw\" is DEPRICATED and no longer supported. It will be removed in the next MAJOR release.");
    }

    const me = this;
    this.defaultOptions = {
      autoResize: true,
      longSelectPressTime: 251,
      orientation: {
        axis: 'bottom',
        item: 'bottom'
      },
      moment,
    };
    this.options = util.deepExtend({}, this.defaultOptions);

    this._create(container);
    if (!options || (options && typeof options.rtl == "undefined")) {
      this.dom.root.style.visibility = 'hidden';
      let directionFromDom;
      let domNode = this.dom.root;
      while (!directionFromDom && domNode) {
        directionFromDom = window.getComputedStyle(domNode, null).direction;
        domNode = domNode.parentElement;
      }
      this.options.rtl = (directionFromDom && (directionFromDom.toLowerCase() == "rtl"));
    } else {
      this.options.rtl = options.rtl;
    }

    if (options) {
      if (options.rollingMode) { this.options.rollingMode = options.rollingMode; }
      if (options.onInitialDrawComplete) { this.options.onInitialDrawComplete = options.onInitialDrawComplete; }
      if (options.onTimeout) { this.options.onTimeout = options.onTimeout; }
      if (options.loadingScreenTemplate) { this.options.loadingScreenTemplate = options.loadingScreenTemplate; }
    }

    const loadingScreenFragment = document.createElement('div');
    if (this.options.loadingScreenTemplate) {
      const templateFunction = this.options.loadingScreenTemplate.bind(this);
      const loadingScreen = templateFunction(this.dom.loadingScreen);
      if ((loadingScreen instanceof Object) && !(loadingScreen instanceof Element)) {
        templateFunction(loadingScreenFragment)
      } else {
        if (loadingScreen instanceof Element) {
          loadingScreenFragment.innerHTML = '';
          loadingScreenFragment.appendChild(loadingScreen);
        }
        else if (loadingScreen != undefined) {
          loadingScreenFragment.innerHTML = util.xss(loadingScreen);
        }
      }
    }
    this.dom.loadingScreen.appendChild(loadingScreenFragment);

    this.components = [];

    this.body = {
      dom: this.dom,
      domProps: this.props,
      emitter: {
        on: this.on.bind(this),
        off: this.off.bind(this),
        emit: this.emit.bind(this)
      },
      hiddenDates: [],
      util: {
        getScale() {
          return me.timeAxis.step.scale;
        },
        getStep() {
          return me.timeAxis.step.step;
        },

        toScreen: me._toScreen.bind(me),
        toGlobalScreen: me._toGlobalScreen.bind(me),
        toTime: me._toTime.bind(me),
        toGlobalTime : me._toGlobalTime.bind(me)
      }
    };

    this.range = new Range(this.body, this.options);
    this.components.push(this.range);
    this.body.range = this.range;

    this.timeAxis = new TimeAxis(this.body, this.options);
    this.timeAxis2 = null;
    this.components.push(this.timeAxis);

    this.currentTime = new CurrentTime(this.body, this.options);
    this.components.push(this.currentTime);

    this.itemSet = new ItemSet(this.body, this.options);
    this.components.push(this.itemSet);

    this.itemsData = null;
    this.groupsData = null;

    function emit(eventName, event) {
      if (!me.hasListeners(eventName)) {
        return;
      }

      me.emit(eventName, me.getEventProperties(event));
    }

    this.dom.root.onclick = event => {
      emit('click', event)
    };
    this.dom.root.ondblclick = event => {
      emit('doubleClick', event)
    };
    this.dom.root.oncontextmenu = event => {
      emit('contextmenu', event)
    };
    this.dom.root.onmouseover = event => {
      emit('mouseOver', event)
    };
    if(window.PointerEvent) {
      this.dom.root.onpointerdown = event => {
        emit('mouseDown', event)
      };
      this.dom.root.onpointermove = event => {
        emit('mouseMove', event)
      };
      this.dom.root.onpointerup = event => {
        emit('mouseUp', event)
      };
    } else {
      this.dom.root.onmousemove = event => {
        emit('mouseMove', event)
      };
      this.dom.root.onmousedown = event => {
        emit('mouseDown', event)
      };
      this.dom.root.onmouseup = event => {
        emit('mouseUp', event)
      };
    }

    this.initialFitDone = false;
    this.on('changed', () => {
      if (me.itemsData == null) return;
      if (!me.initialFitDone && !me.options.rollingMode) {
        me.initialFitDone = true;
        if (me.options.start != undefined || me.options.end != undefined) {
          if (me.options.start == undefined || me.options.end == undefined) {
            var range = me.getItemRange();
          }

          const start = me.options.start != undefined ? me.options.start : range.min;
          const end   = me.options.end   != undefined ? me.options.end   : range.max;
          me.setWindow(start, end, {animation: false});
        } else {
          me.fit({animation: false});
        }
      }

      if (!me.initialDrawDone && (me.initialRangeChangeDone || (!me.options.start && !me.options.end)
        || me.options.rollingMode)) {
        me.initialDrawDone = true;
        me.itemSet.initialDrawDone = true;
        me.dom.root.style.visibility = 'visible';
        me.dom.loadingScreen.parentNode.removeChild(me.dom.loadingScreen);
        if (me.options.onInitialDrawComplete) {
          setTimeout(() => {
            return me.options.onInitialDrawComplete();
          }, 0)
        }
      }
    });

    this.on('destroyTimeline', () => {
      me.destroy()
    });

    if (options) {
      this.setOptions(options);
    }

    this.body.emitter.on('fit', (args) => {
      this._onFit(args);
      this.redraw();
    });

    if (groups) {
