function decodeMap (buf, offset, length, headerLength, options) {
    const _temp = decodeArray(buf, offset, 2 * length, headerLength)
    if (!_temp) return null
    const [ result, consumedBytes ] = _temp

    var isPlainObject = !options.preferMap

    if (isPlainObject) {
      for (let i = 0; i < 2 * length; i += 2) {
        if (typeof result[i] !== 'string') {
          isPlainObject = false
          break
        }
      }
    }

    if (isPlainObject) {
      const object = {}
      for (let i = 0; i < 2 * length; i += 2) {
        const key = result[i]
        const val = result[i + 1]
        object[key] = val
      }
      return [object, consumedBytes]
    } else {
      const mapping = new Map()
      for (let i = 0; i < 2 * length; i += 2) {
        const key = result[i]
        const val = result[i + 1]
        mapping.set(key, val)
      }
      return [mapping, consumedBytes]
    }
  }

function sendFileInformations(file, peer_id, broadcast = false) {
    fileToSend = file;
    if (fileToSend && fileToSend.size > 0) {
        if (!thereIsPeerConnections()) {
            return userLog('info', 'No participants detected');
        }
        let fileInfo = {
            room_id: roomId,
            broadcast: broadcast,
            peer_name: myPeerName,
            peer_id: peer_id,
            file: {
                fileName: fileToSend.name,
                fileSize: fileToSend.size,
                fileType: fileToSend.type,
            },
        };
        appendMessage(myPeerName, rightChatAvatar, 'right', 'Send file: \n' + toHtmlJson(fileInfo), false);
        sendToServer('fileInfo', fileInfo);
        setTimeout(() => {
            sendFileData(peer_id, broadcast);
        }, 1000);
    } else {
        userLog('error', 'File dragged not valid or empty.');
    }
}

function add_review(data, event) {
    var diag_list = [];
    for (var idx = 0; idx < data.issues().length; idx++) {
        var cur_diag = data.issues()[idx];
        if (cur_diag.selected()) {
            diag_list.push(cur_diag.jsonify());
        }
    }

    var proc_list = [];
    for (idx = 0; idx < data.procedures().length; idx++) {
